.ds {
  color:var(--p-ink); background:var(--p-bg); font:var(--p-type-body);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset); }
.ds .ui-icon { display:inline-block; width:var(--p-icon-md); height:var(--p-icon-md); flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--p-text-sm); margin-top:var(--p-space-sm); min-height:calc(var(--p-space-unit) * 5); color:var(--p-muted); }
.ds .ds-surface { border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--p-shadow); border-color:var(--p-edge); }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--p-inset); background:var(--p-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--p-high); box-shadow:var(--p-glass-shadow); }
@supports (backdrop-filter:blur(16px)) { .ds .ds-surface[data-material="glass"] { background:var(--p-glass); backdrop-filter:var(--p-blur-md); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--p-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }
.ds .ds-token-row { display:flex; flex-wrap:wrap; align-items:center; gap:var(--p-space-sm); }

/* Side-by-side options; the chosen one is filled and carries a check, never colour alone. */
.ds .ds-segmented { display:flex; flex-wrap:wrap; min-width:0; margin:0; padding:0; border:0; }
.ds .ds-segmented > legend { position:absolute; width:var(--p-size-hairline); height:var(--p-size-hairline); overflow:hidden; clip-path:inset(50%); white-space:nowrap; }
.ds .ds-segment { position:relative; display:inline-flex; align-items:center; gap:var(--p-space-xs); min-height:var(--p-control-size-sm); padding:var(--p-space-xs) var(--p-space-md); border:var(--p-border-width) solid var(--p-control-border); background:var(--p-bg); font-size:var(--p-text-body); cursor:pointer; }
.ds .ds-segment + .ds-segment { margin-left:calc(var(--p-border-width) * -1); }
.ds .ds-segment:first-of-type { border-radius:var(--p-radius-lg) 0 0 var(--p-radius-lg); }
.ds .ds-segment:last-of-type { border-radius:0 var(--p-radius-lg) var(--p-radius-lg) 0; }
.ds .ds-segment input { position:absolute; inset:0; width:100%; height:100%; margin:0; opacity:0; cursor:inherit; }
.ds .ds-segment:has(:checked) { z-index:var(--p-layer-raised); border-color:var(--p-accent); background:var(--p-accent); color:var(--p-on-accent); font-weight:var(--p-weight-semibold); }
.ds .ds-segment:has(:checked)::before { content:'✓'; content:'✓' / ''; }
.ds .ds-segment:has(:focus-visible) { z-index:var(--p-layer-lifted); outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset-tight); }
.ds .ds-segment:has(:disabled) { border-color:var(--p-line); background:var(--p-disabled); color:var(--p-muted); cursor:not-allowed; }

'use client';
import React, { useId } from 'react';
// Two to four options side by side; the chosen one is filled and carries a check. items: [{ value, label }].
const defaults = [{ value: 'day', label: '일' }, { value: 'week', label: '주' }, { value: 'month', label: '월' }];
export function SegmentedButton({ legend = '보기 단위', items = defaults, value, defaultValue, onValueChange, name, disabled }) {
  const id = useId();
  const own = item => value !== undefined ? { checked: value === item.value } : { defaultChecked: (defaultValue ?? items[0]?.value) === item.value };
  return <fieldset className="ds-segmented" disabled={disabled}><legend>{legend}</legend>{items.map(item => <label key={item.value} className="ds-segment"><input type="radio" name={name ?? id} value={item.value} {...own(item)} onChange={() => onValueChange?.(item.value)} /><span>{item.label}</span></label>)}</fieldset>;
}

